using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Setup: options backed by a source-generated context ---
var options = new JsonSerializerOptions();
options.TypeInfoResolverChain.Add(DemoContext.Default);

// ──────────────────────────────────────────────────────────
// 1. Get strongly-typed metadata: JsonTypeInfo<T>
//    options.GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
// ──────────────────────────────────────────────────────────
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {p}");

// ──────────────────────────────────────────────────────────
// 2. Probe without throwing: TryGetTypeInfo
//    Returns false instead of throwing when metadata is missing.
// ──────────────────────────────────────────────────────────
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"\nProbe Person   → found ({found!.Type.Name})");
else
    Console.WriteLine("\nProbe Person   → not found");

// Order is NOT in the context, so this should return false.
if (options.TryGetTypeInfo(typeof(Order), out _))
    Console.WriteLine("Probe Order    → found");
else
    Console.WriteLine("Probe Order    → not found (as expected)");

// --- Types & source-gen context ---
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);   // deliberately NOT in the context

[JsonSerializable(typeof(Person))]
public partial class DemoContext : JsonSerializerContext;

